"""Coordinator executes only. Writes private Redis config; never starts a process."""
from pathlib import Path
import argparse,json,os
p=argparse.ArgumentParser();p.add_argument('--owned-dir',type=Path,required=True);p.add_argument('--port',type=int,required=True);a=p.parse_args();assert 1024<=a.port<=65535;assert not a.owned_dir.exists();a.owned_dir.mkdir(mode=0o700);a.owned_dir=a.owned_dir.resolve();sock=a.owned_dir/'r%#?@.sock';assert len(os.fsencode(sock))<100,'portable UNIX path must be short';password=os.environ.get('NODE_ADDRESS_REDIS_PASSWORD');assert password and all(32<=ord(c)<127 for c in password),'owned synthetic ASCII secret required';config=a.owned_dir/'redis.conf';config.write_text('bind 127.0.0.1 ::1\nport '+str(a.port)+'\nunixsocket '+str(sock)+'\nunixsocketperm 700\nprotected-mode yes\nsave ""\nappendonly no\ndaemonize no\nrequirepass '+json.dumps(password)+'\ndir '+json.dumps(str(a.owned_dir))+'\n');config.chmod(0o600);(a.owned_dir/'OWNED.json').write_text(json.dumps({'schema':1,'uid':os.getuid(),'unix_socket':str(sock),'port':a.port,'scope':'exclusive root-coordinator-owned synthetic Redis only'})+'\n');print(config)
